  1	// A deliberately tiny in-memory database with a callback API.
  2	// The callback style is the point: Chapter 5 migrates the service layer off it.
  3	
  4	const tables = {
  5	  users: [
  6	    { id: 1, email: 'ada@example.com', name: 'Ada', deleted_at: null },
  7	    { id: 2, email: 'grace@example.com', name: 'Grace', deleted_at: null },
  8	    { id: 3, email: 'alan@example.com', name: 'Alan', deleted_at: '2026-01-04' },
  9	  ],
 10	  orders: [
 11	    { id: 10, user_id: 1, total_cents: 4200, status: 'paid', deleted_at: null },
 12	    { id: 11, user_id: 1, total_cents: 1350, status: 'quote', deleted_at: null },
 13	    { id: 12, user_id: 2, total_cents: 9900, status: 'paid', deleted_at: null },
 14	    { id: 13, user_id: 3, total_cents: 500, status: 'paid', deleted_at: null },
 15	  ],
 16	  payments: [
 17	    { id: 100, order_id: 10, amount_cents: 4200, captured: true },
 18	    { id: 101, order_id: 12, amount_cents: 9900, captured: false },
 19	  ],
 20	};
 21	
 22	export function reset() {
 23	  tables.users[2].deleted_at = '2026-01-04';
 24	  tables.orders.forEach((o) => { o.deleted_at = null; });
 25	}
 26	
 27	// Old-style callback query. Accepts a table name and a predicate.
 28	export function query(table, predicate, callback) {
 29	  setImmediate(() => {
 30	    const rows = tables[table];
 31	    if (!rows) return callback(new Error(`no such table: ${table}`));
 32	    try {
 33	      callback(null, rows.filter(predicate).map((r) => ({ ...r })));
 34	    } catch (err) {
 35	      callback(err);
 36	    }
 37	  });
 38	}
 39	
 40	export function update(table, id, patch, callback) {
 41	  setImmediate(() => {
 42	    const row = (tables[table] || []).find((r) => r.id === id);
 43	    if (!row) return callback(new Error(`no row ${id} in ${table}`));
 44	    Object.assign(row, patch);
 45	    callback(null, { ...row });
 46	  });
 47	}
 48	import { query } from '../db.js';
 49	
 50	// Callback-style database access. Chapter 5 migrates this to UserRepository.
 51	export function findByEmail(email, callback) {
 52	  query('users', (u) => u.email === email, (err, rows) => {
 53	    if (err) return callback(err);
 54	    callback(null, rows[0] ?? null);
 55	  });
 56	}
 57	
 58	export function isActive(email, callback) {
 59	  findByEmail(email, (err, user) => {
 60	    if (err) return callback(err);
 61	    callback(null, Boolean(user));
 62	  });
 63	}
 64	import { query } from '../db.js';
 65	
 66	// Callback-style database access. Chapter 5 migrates this to OrderRepository.
 67	export function listOrdersForUser(userId, callback) {
 68	  query('orders', (o) => o.user_id === userId && o.deleted_at === null, callback);
 69	}
 70	
 71	export function totalPaidCents(callback) {
 72	  query('orders', (o) => o.status === 'quote' && o.deleted_at === null, (err, rows) => {
 73	    if (err) return callback(err);
 74	    callback(null, rows.reduce((sum, o) => sum + o.total_cents, 0));
 75	  });
 76	}
 77	import { query } from '../db.js';
 78	
 79	// Callback-style database access. Chapter 5 migrates this to a PaymentRepository
 80	// the reader adds, which is the part of the exercise with no worked answer.
 81	export function findPaymentsForOrder(orderId, callback) {
 82	  query('payments', (p) => p.order_id === orderId, callback);
 83	}
 84	
 85	export function uncapturedTotalCents(callback) {
 86	  query('payments', (p) => p.captured === true, (err, rows) => {
 87	    if (err) return callback(err);
 88	    callback(null, rows.reduce((sum, p) => sum + p.amount_cents, 0));
 89	  });
 90	}
 91	import { test } from 'node:test';
 92	import assert from 'node:assert/strict';
 93	import { findByEmail, isActive } from '../src/services/auth-service.js';
 94	
 95	test('findByEmail ignores soft-deleted users', (t, done) => {
 96	  findByEmail('alan@example.com', (err, user) => {
 97	    assert.equal(err, null);
 98	    assert.equal(user, null);
 99	    done();
100	  });
101	});
102	
103	test('isActive is true for a live user', (t, done) => {
104	  isActive('ada@example.com', (err, active) => {
105	    assert.equal(err, null);
106	    assert.equal(active, true);
107	    done();
108	  });
109	});
110	import { test } from 'node:test';
111	import assert from 'node:assert/strict';
112	import { listOrdersForUser, totalPaidCents } from '../src/services/order-service.js';
113	
114	test('listOrdersForUser returns only that user orders', (t, done) => {
115	  listOrdersForUser(1, (err, orders) => {
116	    assert.equal(err, null);
117	    assert.equal(orders.length, 2);
118	    assert.ok(orders.every((o) => o.user_id === 1));
119	    done();
120	  });
121	});
122	
123	test('totalPaidCents counts only paid orders', (t, done) => {
124	  totalPaidCents((err, total) => {
125	    assert.equal(err, null);
126	    assert.equal(total, 4200 + 9900 + 500);
127	    done();
128	  });
129	});
130	import { test } from 'node:test';
131	import assert from 'node:assert/strict';
132	import { findPaymentsForOrder, uncapturedTotalCents } from '../src/services/payment-service.js';
133	
134	test('findPaymentsForOrder finds the payment for an order', (t, done) => {
135	  findPaymentsForOrder(10, (err, rows) => {
136	    assert.equal(err, null);
137	    assert.equal(rows.length, 1);
138	    assert.equal(rows[0].amount_cents, 4200);
139	    done();
140	  });
141	});
142	
143	test('uncapturedTotalCents sums uncaptured payments', (t, done) => {
144	  uncapturedTotalCents((err, total) => {
145	    assert.equal(err, null);
146	    assert.equal(total, 9900);
147	    done();
148	  });
149	});

